import java.util.Scanner;

public class Main {
    static long p, q, r;

    static long getGCD(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p = sc.nextLong();
        q = sc.nextLong();
        r = sc.nextLong();

        if (q <= r) {
            long g = getGCD(p, q);
            p /= g;
            q /= g;
            System.out.println(p + "/" + q);
            return;
        }
        if (p == q) {
            System.out.println("1/1");
            return;
        }

        double bestDiff = 1e18;
        double ratio = (double) p / (double) q;
        long numerator = 0, denominator = 1;
        long leftBound = 0, rightBound = q;

        for (long i = 1; i <= r; ++i) {
            while (i * p > rightBound) {
                leftBound += q;
                rightBound += q;
            }
            if (i * p >= leftBound && i * p <= rightBound) {
                long low = leftBound / q;
                long high = rightBound / q;
                double lowRatio = (double) low / (double) i;
                double highRatio = (double) high / (double) i;
                double diffLow = Math.abs(ratio - lowRatio);
                double diffHigh = Math.abs(ratio - highRatio);
                if (diffHigh < diffLow) {
                    if (diffHigh < bestDiff) {
                        bestDiff = diffHigh;
                        numerator = high;
                        denominator = i;
                    }
                } else {
                    if (diffLow < bestDiff) {
                        bestDiff = diffLow;
                        numerator = low;
                        denominator = i;
                    }
                }
            }
        }
        long g = getGCD(numerator, denominator);
        numerator /= g;
        denominator /= g;
        System.out.println(numerator + "/" + denominator);
    }
}
